insert into public.cards (id, owner_id, data) values
('9efb2c0e-eb18-486f-9f6e-44fc9f0c2c35', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "9efb2c0e-eb18-486f-9f6e-44fc9f0c2c35", "code": "32ER-007", "origin": "ER", "subject": "Mathématiques", "level": "3e", "theme": "Fonctions", "tags": ["3e", "Fonctions", "fonction affine", "cours", "image", "antécédent", "vocabulaire"], "front": "**Image** et **antécédent** : quelle différence ? Comment trouve-t-on chacun ?", "back": "**Image** : on donne $x$, on cherche $f(x)$ : on **remplace** $x$ dans l''expression.\n**Antécédent** : on donne $f(x) = k$, on cherche $x$ : on **résout** l''équation $ax + b = k$.", "createdAt": 1792405693196, "updatedAt": 1792405693196, "ocrDone": true}'::jsonb),
('adfe2efc-07d7-4078-b1bc-81014c11a229', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "adfe2efc-07d7-4078-b1bc-81014c11a229", "code": "32ER-008", "origin": "ER", "subject": "Mathématiques", "level": "3e", "theme": "Fonctions", "tags": ["3e", "Fonctions", "fonction affine", "cours", "reconnaître", "méthode"], "front": "Comment reconnaître qu''une fonction est **affine** ?", "back": "Son expression peut s''écrire $ax + b$, après avoir **développé et réduit**.\nAffines : $3x$, $5$, $\\dfrac{x}{2} + 1$, $(x+1)^2 - x^2$.\nPas affines : $x^2$, $\\dfrac{1}{x}$, $\\sqrt{x}$.", "createdAt": 1792405693197, "updatedAt": 1792405693197, "ocrDone": true}'::jsonb),
('38ee7b01-2343-4abf-9ee4-6a50625811a6', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "38ee7b01-2343-4abf-9ee4-6a50625811a6", "code": "32ER-009", "origin": "ER", "subject": "Mathématiques", "level": "3e", "theme": "Fonctions", "tags": ["3e", "Fonctions", "fonction affine", "cours", "représentation graphique", "linéaire", "constante"], "front": "Sur un graphique, comment reconnaître une fonction **linéaire**, **affine**, **constante** ?", "back": "**Linéaire** : droite qui passe par l''**origine**.\n**Affine** : droite (non verticale) quelconque.\n**Constante** : droite **horizontale**.", "createdAt": 1792405693198, "updatedAt": 1792405693198, "ocrDone": true}'::jsonb),
('44687d1b-c19b-4233-a9ee-92db09a007d0', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "44687d1b-c19b-4233-a9ee-92db09a007d0", "code": "32ER-010", "origin": "ER", "subject": "Mathématiques", "level": "3e", "theme": "Fonctions", "tags": ["3e", "Fonctions", "fonction affine", "cours", "tracer", "méthode", "droite"], "front": "Méthode : tracer rapidement la droite $y = ax + b$ sans tableau de valeurs.", "back": "1. Placer le point $(0\\,;\\,b)$ sur l''axe des ordonnées.<br>2. Depuis ce point, avancer de **1** vers la droite et monter de $a$ (descendre si $a < 0$).<br>3. Tracer la droite par ces deux points.<svg viewBox=\"0 0 220 150\" width=\"220\" height=\"150\" xmlns=\"http://www.w3.org/2000/svg\" style=\"display:block;margin:8px auto\"><line x1=\"20\" y1=\"5\" x2=\"20\" y2=\"145\" stroke=\"#e5e2da\"/><line x1=\"40\" y1=\"5\" x2=\"40\" y2=\"145\" stroke=\"#e5e2da\"/><line x1=\"60\" y1=\"5\" x2=\"60\" y2=\"145\" stroke=\"#e5e2da\"/><line x1=\"80\" y1=\"5\" x2=\"80\" y2=\"145\" stroke=\"#e5e2da\"/><line x1=\"100\" y1=\"5\" x2=\"100\" y2=\"145\" stroke=\"#e5e2da\"/><line x1=\"120\" y1=\"5\" x2=\"120\" y2=\"145\" stroke=\"#e5e2da\"/><line x1=\"140\" y1=\"5\" x2=\"140\" y2=\"145\" stroke=\"#e5e2da\"/><line x1=\"160\" y1=\"5\" x2=\"160\" y2=\"145\" stroke=\"#e5e2da\"/><line x1=\"180\" y1=\"5\" x2=\"180\" y2=\"145\" stroke=\"#e5e2da\"/><line x1=\"200\" y1=\"5\" x2=\"200\" y2=\"145\" stroke=\"#e5e2da\"/><line x1=\"10\" y1=\"140\" x2=\"210\" y2=\"140\" stroke=\"#e5e2da\"/><line x1=\"10\" y1=\"120\" x2=\"210\" y2=\"120\" stroke=\"#e5e2da\"/><line x1=\"10\" y1=\"100\" x2=\"210\" y2=\"100\" stroke=\"#e5e2da\"/><line x1=\"10\" y1=\"80\" x2=\"210\" y2=\"80\" stroke=\"#e5e2da\"/><line x1=\"10\" y1=\"60\" x2=\"210\" y2=\"60\" stroke=\"#e5e2da\"/><line x1=\"10\" y1=\"40\" x2=\"210\" y2=\"40\" stroke=\"#e5e2da\"/><line x1=\"10\" y1=\"20\" x2=\"210\" y2=\"20\" stroke=\"#e5e2da\"/><line x1=\"10\" y1=\"120\" x2=\"210\" y2=\"120\" stroke=\"#555\" stroke-width=\"1.5\"/><line x1=\"40\" y1=\"145\" x2=\"40\" y2=\"5\" stroke=\"#555\" stroke-width=\"1.5\"/><text x=\"56\" y=\"134\" font-size=\"11\" fill=\"#555\">1</text><text x=\"28\" y=\"104\" font-size=\"11\" fill=\"#555\">1</text><line x1=\"20\" y1=\"140\" x2=\"100\" y2=\"-20\" stroke=\"#1d5fa8\" stroke-width=\"3\"/><circle cx=\"40\" cy=\"100\" r=\"4\" fill=\"#c0392b\"/><line x1=\"40\" y1=\"100\" x2=\"60\" y2=\"100\" stroke=\"#c0392b\" stroke-width=\"2.5\"/><line x1=\"60\" y1=\"100\" x2=\"60\" y2=\"60\" stroke=\"#c0392b\" stroke-width=\"2.5\"/><text x=\"43\" y=\"114\" font-size=\"12\" font-weight=\"bold\" fill=\"#c0392b\">+1</text><text x=\"66\" y=\"84\" font-size=\"12\" font-weight=\"bold\" fill=\"#c0392b\">+a</text><text x=\"8\" y=\"96\" font-size=\"12\" font-weight=\"bold\" fill=\"#c0392b\">b</text></svg>", "createdAt": 1792405693199, "updatedAt": 1792405693199, "ocrDone": true}'::jsonb),
('d8a789d3-2760-4f96-9688-eeba7c0dac51', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "d8a789d3-2760-4f96-9688-eeba7c0dac51", "code": "32ER-011", "origin": "ER", "subject": "Mathématiques", "level": "3e", "theme": "Fonctions", "tags": ["3e", "Fonctions", "fonction affine", "cours", "proportionnalité", "linéaire"], "front": "Une situation modélisée par $f(x) = ax + b$ avec $b \\neq 0$ est-elle une situation de **proportionnalité** ?", "back": "**Non** : il n''y a proportionnalité que si $b = 0$ (fonction linéaire, droite par l''origine).\nMais les **accroissements** restent proportionnels : $\\Delta y = a\\,\\Delta x$.", "createdAt": 1792405693200, "updatedAt": 1792405693200, "ocrDone": true}'::jsonb),
('e5c560fe-1368-49a4-a13f-a41e8906848b', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "e5c560fe-1368-49a4-a13f-a41e8906848b", "code": "22ER-008", "origin": "ER", "subject": "Mathématiques", "level": "2nde", "theme": "Fonctions", "tags": ["2nde", "Fonctions", "fonction affine", "cours", "coefficient directeur", "interprétation", "modélisation"], "front": "Dans une situation concrète, que représente le **coefficient directeur** $a$ ?", "back": "La variation de $y$ quand $x$ augmente de **1** : un taux (€ par pièce, mm par newton, km par heure…).\nSon unité : unité de $y$ / unité de $x$.", "createdAt": 1792405693201, "updatedAt": 1792405693201, "ocrDone": true}'::jsonb),
('2790ab4c-50c1-4a45-bea1-0fd25b66736e', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "2790ab4c-50c1-4a45-bea1-0fd25b66736e", "code": "22ER-009", "origin": "ER", "subject": "Mathématiques", "level": "2nde", "theme": "Fonctions", "tags": ["2nde", "Fonctions", "fonction affine", "cours", "ordonnée à l''origine", "interprétation", "modélisation"], "front": "Dans une situation concrète, que représente l''**ordonnée à l''origine** $b$ ?", "back": "La valeur de $y$ quand $x = 0$ : la **valeur de départ** (frais fixes, longueur à vide d''un ressort, position initiale…).", "createdAt": 1792405693202, "updatedAt": 1792405693202, "ocrDone": true}'::jsonb),
('b0baaec2-d07b-4710-a76c-0ff824cbd5c6', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "b0baaec2-d07b-4710-a76c-0ff824cbd5c6", "code": "22ER-010", "origin": "ER", "subject": "Mathématiques", "level": "2nde", "theme": "Fonctions", "tags": ["2nde", "Fonctions", "fonction affine", "cours", "accroissements", "propriété"], "front": "Propriété des **accroissements** d''une fonction affine $f(x) = ax + b$ ?", "back": "Ils sont proportionnels : $f(x_2) - f(x_1) = a\\,(x_2 - x_1)$, soit $\\Delta y = a\\,\\Delta x$.\nC''est pourquoi $a = \\dfrac{\\Delta y}{\\Delta x}$ est le même entre deux points quelconques de la droite.", "createdAt": 1792405693203, "updatedAt": 1792405693203, "ocrDone": true}'::jsonb),
('130fe369-7e2a-4cdc-a2c0-b5d887032ee7', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "130fe369-7e2a-4cdc-a2c0-b5d887032ee7", "code": "22ER-011", "origin": "ER", "subject": "Mathématiques", "level": "2nde", "theme": "Fonctions", "tags": ["2nde", "Fonctions", "fonction affine", "cours", "inéquation", "méthode", "piège"], "front": "Résoudre $ax + b > 0$ : à quoi faut-il faire attention ?", "back": "On isole $x$ : $ax > -b$, puis on divise par $a$.\n**Si $a < 0$, le sens de l''inégalité change** : $x < -\\dfrac{b}{a}$.\nRéflexe : vérifier avec le signe de $a$ (signe de $a$ à droite de la racine).", "createdAt": 1792405693204, "updatedAt": 1792405693204, "ocrDone": true}'::jsonb),
('0d13ae6f-5a8d-4308-9d89-a01b7a4dadf6', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "0d13ae6f-5a8d-4308-9d89-a01b7a4dadf6", "code": "12ER-017", "origin": "ER", "subject": "Mathématiques", "level": "1re", "theme": "Fonctions", "tags": ["1re", "Fonctions", "fonction affine", "cours", "dérivée", "tangente", "nombre dérivé"], "front": "**Dérivée** d''une fonction affine $f(x) = ax + b$ ? Que vaut sa tangente en un point ?", "back": "$f''(x) = a$ : la dérivée est **constante**, égale au coefficient directeur.\nLa tangente en tout point est la droite elle-même : le nombre dérivé, c''est la **pente**.", "createdAt": 1792405693205, "updatedAt": 1792405693205, "ocrDone": true}'::jsonb);
