begin;
update public.tutoring_sessions set data = jsonb_set(data, '{cardIds}', coalesce(data->'cardIds', '[]'::jsonb) || '["9efb2c0e-eb18-486f-9f6e-44fc9f0c2c35", "adfe2efc-07d7-4078-b1bc-81014c11a229", "38ee7b01-2343-4abf-9ee4-6a50625811a6", "44687d1b-c19b-4233-a9ee-92db09a007d0", "d8a789d3-2760-4f96-9688-eeba7c0dac51", "e5c560fe-1368-49a4-a13f-a41e8906848b", "2790ab4c-50c1-4a45-bea1-0fd25b66736e", "b0baaec2-d07b-4710-a76c-0ff824cbd5c6", "130fe369-7e2a-4cdc-a2c0-b5d887032ee7", "0d13ae6f-5a8d-4308-9d89-a01b7a4dadf6"]'::jsonb) where id = 'cddf0538-53e2-49ed-b9ba-0fe3eab534e5';
commit;
select data->>'date' as seance, jsonb_array_length(data->'cardIds') as flashcards from public.tutoring_sessions where id = 'cddf0538-53e2-49ed-b9ba-0fe3eab534e5';
select data->>'code' as code, data->>'level' as niveau, left(data->>'front', 70) as recto from public.cards where id in ('9efb2c0e-eb18-486f-9f6e-44fc9f0c2c35','adfe2efc-07d7-4078-b1bc-81014c11a229','38ee7b01-2343-4abf-9ee4-6a50625811a6','44687d1b-c19b-4233-a9ee-92db09a007d0','d8a789d3-2760-4f96-9688-eeba7c0dac51','e5c560fe-1368-49a4-a13f-a41e8906848b','2790ab4c-50c1-4a45-bea1-0fd25b66736e','b0baaec2-d07b-4710-a76c-0ff824cbd5c6','130fe369-7e2a-4cdc-a2c0-b5d887032ee7','0d13ae6f-5a8d-4308-9d89-a01b7a4dadf6') order by data->>'code';
